//! Stress scenes (ADR 0008 §10): games generated by code, by name, that every renderer change is measured against.
//!
//! Each scene is built into a game's `Workspace` from a seed, so the same name and seed always give the same parts in
//! the same places ([`StressScene::build`]). 1% of the parts move: [`StressScene::animate`] gives each of them a new
//! `CFrame` for a point in time, so every frame changes the same parts the same way.
//!
//! | Name | What | Window |
//! |---|---|---|
//! | `parts_10k`, `parts_50k`, `parts_100k` | A city of static parts (70% blocks, 10% each balls, cylinders, wedges; eight materials) on a baseplate, one part per 16 m², seen from the middle at head height; 1% moving | 1920 × 1080 |
//! | `many_lights` | A lit town: 2,500 parts plus 1,152 lamps, each a neon ball holding a `PointLight` (1,024) or a `SpotLight` (128), 16 of them with shadows; 1% of the lamps moving. Only the temporary sun renders until lights do (#81, #83) | 1920 × 1080 |
//! | `overdraw` | A hall seen from inside, crossed by 64 walls between 2 and 41 m away, each covering the whole view but for a window, in the order the renderer then draws back to front, so every wall overdraws the ones behind it (up to 64 layers per pixel); glass in a tenth of the windows, 3,000 crates on the floor; 1% moving | 1920 × 1080 |
//! | `mobile` | 5,000 parts, the city's mix, with 25 see-through ones; 1% moving | 1280 × 720 |
//! | `see_through_10k` | 10,000 see-through blocks and balls on a lattice, the shapes alternating so that sorted back to front they interleave (#106), over an opaque floor; 1% moving | 1920 × 1080 |
//!
//! Window sizes are logical pixels: what a benchmark asks for ([`StressKind::window_size`]). The builders work in
//! any build (they only need the classes); running a scene and measuring it is [`bench`] (the `render` feature).

#[cfg(feature = "render")]
pub mod bench;

#[cfg(feature = "render")]
pub use bench::{BenchOptions, BenchReport, run_bench};

use metallic_core::glam::{Quat, Vec3};
use metallic_core::{CFrame, ClassId, Color3, DataModel, DmError, EnumItem, Id, PropId, Value};
use thiserror::Error;

/// Why a stress scene could not be built.
#[derive(Debug, Error)]
#[non_exhaustive]
pub enum StressError {
    /// No scene has this name ([`StressKind::from_name`]).
    #[error("no stress scene is called {0:?}; the scenes are {list}", list = StressKind::names().join(", "))]
    UnknownScene(String),
    /// The game lacks a class or service a scene needs.
    #[error("the game has no {0}")]
    Missing(&'static str),
    /// The data model refused a change.
    #[error(transparent)]
    Dm(#[from] DmError),
}

/// Which stress scene; see the [module documentation](self).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum StressKind {
    /// 10,000 static parts, 1% moving.
    Parts10k,
    /// 50,000 static parts, 1% moving.
    Parts50k,
    /// 100,000 static parts, 1% moving.
    Parts100k,
    /// A town with 1,152 lights.
    ManyLights,
    /// A heavy-overdraw interior.
    Overdraw,
    /// A scene sized for phones.
    Mobile,
    /// 10,000 interleaved see-through blocks and balls.
    SeeThrough10k,
}

impl StressKind {
    /// Every scene, in the order the docs list them.
    pub const ALL: [StressKind; 7] = [
        StressKind::Parts10k,
        StressKind::Parts50k,
        StressKind::Parts100k,
        StressKind::ManyLights,
        StressKind::Overdraw,
        StressKind::Mobile,
        StressKind::SeeThrough10k,
    ];

    /// The scene's name (`parts_100k`, ...).
    pub const fn name(self) -> &'static str {
        match self {
            StressKind::Parts10k => "parts_10k",
            StressKind::Parts50k => "parts_50k",
            StressKind::Parts100k => "parts_100k",
            StressKind::ManyLights => "many_lights",
            StressKind::Overdraw => "overdraw",
            StressKind::Mobile => "mobile",
            StressKind::SeeThrough10k => "see_through_10k",
        }
    }

    /// Every scene's name.
    pub fn names() -> [&'static str; 7] {
        Self::ALL.map(Self::name)
    }

    /// The scene called `name`.
    pub fn from_name(name: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|kind| kind.name() == name)
    }

    /// The window a benchmark of this scene opens, in logical pixels.
    pub const fn window_size(self) -> (u32, u32) {
        match self {
            StressKind::Mobile => (1280, 720),
            _ => (1920, 1080),
        }
    }
}

/// A part that moves: where it rests and how it moves.
#[derive(Clone, Copy, Debug)]
struct Mover {
    id: Id,
    rest: CFrame,
    /// Seconds of offset into the motion, so movers are out of step.
    phase: f32,
    /// Up and down, metres.
    bob: f32,
    /// Turns per second about the vertical.
    spin: f32,
}

/// A built stress scene: what it holds and which parts move. See the [module documentation](self).
#[derive(Clone, Debug)]
pub struct StressScene {
    kind: StressKind,
    seed: u64,
    parts: usize,
    see_through: usize,
    lights: usize,
    in_view: usize,
    /// Every part's centre as built, to count what a changed view sees.
    centres: Vec<Vec3>,
    camera: Id,
    view: (CFrame, f32),
    cframe: PropId,
    movers: Vec<Mover>,
}

impl StressScene {
    /// Builds `kind` into `dm`'s `Workspace` from `seed`, and points `Workspace.CurrentCamera` at it. The game
    /// should be empty (a new game): the scene adds to whatever is there.
    pub fn build(dm: &mut DataModel, kind: StressKind, seed: u64) -> Result<Self, StressError> {
        let mut builder = Builder::new(dm, seed)?;
        match kind {
            StressKind::Parts10k => builder.city(10_000, 0)?,
            StressKind::Parts50k => builder.city(50_000, 0)?,
            StressKind::Parts100k => builder.city(100_000, 0)?,
            StressKind::Mobile => builder.city(5_000, 25)?,
            StressKind::ManyLights => builder.lit_town()?,
            StressKind::Overdraw => builder.hall()?,
            StressKind::SeeThrough10k => builder.lattice()?,
        }
        builder.finish(kind, seed)
    }

    /// Builds the scene called `name`; see [`StressScene::build`].
    pub fn build_named(dm: &mut DataModel, name: &str, seed: u64) -> Result<Self, StressError> {
        let kind = StressKind::from_name(name).ok_or_else(|| StressError::UnknownScene(name.to_owned()))?;
        Self::build(dm, kind, seed)
    }

    /// Moves the moving parts to where they are at `time` seconds: each bobs up and down and turns about the
    /// vertical, out of step with the others. The same time always gives the same `CFrame`s.
    pub fn animate(&self, dm: &mut DataModel, time: f64) -> Result<(), DmError> {
        // f32 keeps the motion smooth for hours; past that the phase wraps.
        let t = (time % 3600.0) as f32;
        for mover in &self.movers {
            let t = t + mover.phase;
            let lift = Vec3::Y * (mover.bob * (t * 1.7).sin());
            let turn = Quat::from_rotation_y(t * mover.spin * std::f32::consts::TAU);
            let cframe = CFrame::from_parts(mover.rest.position() + lift, mover.rest.rotation() * turn);
            dm.set(mover.id, self.cframe, Value::CFrame(cframe))?;
        }
        Ok(())
    }

    /// Which scene this is.
    pub fn kind(&self) -> StressKind {
        self.kind
    }

    /// The seed it was built from.
    pub fn seed(&self) -> u64 {
        self.seed
    }

    /// Parts in the scene (lamps included, lights not).
    pub fn parts(&self) -> usize {
        self.parts
    }

    /// Parts that are partly see-through.
    pub fn see_through(&self) -> usize {
        self.see_through
    }

    /// Light instances.
    pub fn lights(&self) -> usize {
        self.lights
    }

    /// Parts that move ([`StressScene::animate`]).
    pub fn moving(&self) -> usize {
        self.movers.len()
    }

    /// Parts whose centre is inside the camera's view at a 16:9 aspect: what a culled frame would draw, roughly.
    pub fn in_view(&self) -> usize {
        self.in_view
    }

    /// The camera's vertical field of view in degrees.
    pub fn field_of_view(&self) -> f32 {
        self.view.1
    }

    /// Changes the camera's vertical field of view to `field_of_view` degrees (a narrower view sees fewer parts:
    /// how culling scales is measured this way) and counts the parts in view again.
    pub fn set_field_of_view(&mut self, dm: &mut DataModel, field_of_view: f32) -> Result<(), DmError> {
        dm.set_by_name(self.camera, "FieldOfView", Value::Number(f64::from(field_of_view)))?;
        self.view.1 = field_of_view;
        self.in_view = count_in_view(&self.centres, self.view.0, field_of_view, 16.0 / 9.0);
        Ok(())
    }
}

/// A small, fast, seedable generator (SplitMix64): the same seed gives the same scene on every machine.
#[derive(Clone, Debug)]
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    /// Uniform in `[0, 1)`.
    fn unit(&mut self) -> f32 {
        (self.next() >> 40) as f32 / (1u64 << 24) as f32
    }

    /// Uniform in `[lo, hi)`.
    fn range(&mut self, lo: f32, hi: f32) -> f32 {
        lo + (hi - lo) * self.unit()
    }

    /// Uniform in `0..n` (`n > 0`).
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }

    fn pick<T: Copy>(&mut self, items: &[T]) -> T {
        items[self.below(items.len())]
    }
}

/// How a part looks.
#[derive(Clone, Copy, Debug, PartialEq)]
struct Look {
    shape: &'static str,
    material: &'static str,
    color: [u8; 3],
    transparency: f64,
}

const PALETTE: [[u8; 3]; 12] = [
    [163, 162, 165],
    [196, 40, 28],
    [13, 105, 172],
    [75, 151, 75],
    [245, 205, 48],
    [218, 133, 65],
    [99, 95, 98],
    [242, 243, 243],
    [27, 42, 53],
    [160, 95, 53],
    [107, 50, 124],
    [4, 175, 236],
];

const MATERIALS: [&str; 7] = [
    "Plastic",
    "SmoothPlastic",
    "Metal",
    "Wood",
    "Concrete",
    "Grass",
    "Plastic",
];

/// The ids the builder writes through, looked up once.
struct Props {
    shape: PropId,
    material: PropId,
    size: PropId,
    cframe: PropId,
    color: PropId,
    transparency: PropId,
    anchored: PropId,
}

/// Builds one scene; see [`StressScene::build`].
struct Builder<'a> {
    dm: &'a mut DataModel,
    rng: Rng,
    workspace: Id,
    camera: Id,
    part: ClassId,
    props: Props,
    /// Enum items made once and cloned (an `Arc`) per part.
    shapes: [(&'static str, EnumItem); 4],
    materials: Vec<(&'static str, EnumItem)>,
    parts: usize,
    see_through: usize,
    lights: usize,
    centres: Vec<Vec3>,
    movers: Vec<Mover>,
    view: (CFrame, f32),
}

impl<'a> Builder<'a> {
    fn new(dm: &'a mut DataModel, seed: u64) -> Result<Self, StressError> {
        let registry = dm.registry().clone();
        let part = registry.class_id("Part").ok_or(StressError::Missing("Part class"))?;
        let workspace_class = registry
            .class_id("Workspace")
            .ok_or(StressError::Missing("Workspace class"))?;
        let workspace = dm.service(workspace_class).ok_or(StressError::Missing("Workspace"))?;
        let Value::Ref(Some(camera)) = dm.get_by_name(workspace, "CurrentCamera")? else {
            return Err(StressError::Missing("Workspace.CurrentCamera"));
        };
        let prop = |name: &'static str| registry.prop_id(part, name).ok_or(StressError::Missing(name));
        let props = Props {
            shape: prop("Shape")?,
            material: prop("Material")?,
            size: prop("Size")?,
            cframe: prop("CFrame")?,
            color: prop("Color")?,
            transparency: prop("Transparency")?,
            anchored: prop("Anchored")?,
        };
        let shape = |name| (name, EnumItem::new("PartShape", name));
        let materials = [
            "Plastic",
            "SmoothPlastic",
            "Metal",
            "Wood",
            "Glass",
            "Neon",
            "Concrete",
            "Grass",
        ]
        .into_iter()
        .map(|name| (name, EnumItem::new("Material", name)))
        .collect();
        Ok(Self {
            dm,
            rng: Rng(seed),
            workspace,
            camera,
            part,
            props,
            shapes: [shape("Block"), shape("Ball"), shape("Cylinder"), shape("Wedge")],
            materials,
            parts: 0,
            see_through: 0,
            lights: 0,
            centres: Vec::new(),
            movers: Vec::new(),
            view: (CFrame::IDENTITY, 70.0),
        })
    }

    fn enum_item<'i>(items: &'i [(&'static str, EnumItem)], name: &str) -> Option<&'i EnumItem> {
        items.iter().find(|(n, _)| *n == name).map(|(_, item)| item)
    }

    /// Adds an anchored part to `parent` (the `Workspace` when `None`).
    fn part(&mut self, look: Look, size: Vec3, cframe: CFrame, parent: Option<Id>) -> Result<Id, StressError> {
        let p = &self.props;
        let shape = Self::enum_item(&self.shapes, look.shape).ok_or(StressError::Missing("a part shape"))?;
        let material = Self::enum_item(&self.materials, look.material).ok_or(StressError::Missing("a material"))?;
        let id = self.dm.create(self.part)?;
        self.dm.set(id, p.shape, Value::Enum(shape.clone()))?;
        self.dm.set(id, p.material, Value::Enum(material.clone()))?;
        self.dm.set(id, p.size, Value::Vector3(size))?;
        self.dm.set(id, p.cframe, Value::CFrame(cframe))?;
        let [r, g, b] = look.color;
        self.dm.set(id, p.color, Value::Color3(Color3::from_rgb_u8(r, g, b)))?;
        if look.transparency != 0.0 {
            self.dm.set(id, p.transparency, Value::Number(look.transparency))?;
            self.see_through += 1;
        }
        self.dm.set(id, p.anchored, Value::Bool(true))?;
        self.dm.set_parent(id, Some(parent.unwrap_or(self.workspace)))?;
        self.parts += 1;
        self.centres.push(cframe.position());
        Ok(id)
    }

    /// Makes `id` one of the moving parts.
    fn moving(&mut self, id: Id, rest: CFrame) {
        let mover = Mover {
            id,
            rest,
            phase: self.rng.range(0.0, 10.0),
            bob: self.rng.range(0.5, 2.0),
            spin: self.rng.range(-0.5, 0.5),
        };
        self.movers.push(mover);
    }

    fn set_camera(&mut self, eye: Vec3, target: Vec3, field_of_view: f32) -> Result<(), StressError> {
        let cframe = CFrame::look_at(eye, target, Vec3::Y);
        self.dm.set_by_name(self.camera, "CFrame", Value::CFrame(cframe))?;
        self.dm
            .set_by_name(self.camera, "FieldOfView", Value::Number(f64::from(field_of_view)))?;
        self.view = (cframe, field_of_view);
        Ok(())
    }

    /// A random look from the city mix: 70% blocks, 10% each of the round shapes and wedges.
    fn city_look(&mut self) -> Look {
        let shape = match self.rng.below(10) {
            0 => "Ball",
            1 => "Cylinder",
            2 => "Wedge",
            _ => "Block",
        };
        Look {
            shape,
            material: self.rng.pick(&MATERIALS),
            color: self.rng.pick(&PALETTE),
            transparency: 0.0,
        }
    }

    /// `count` parts (the baseplate included) on a square field, one per 16 m², `see_through` of them glass,
    /// 1% moving, seen from the middle at head height.
    fn city(&mut self, count: usize, see_through: usize) -> Result<(), StressError> {
        self.dm.reserve(count);
        let side = ((count as f32) * 16.0).sqrt();
        self.part(
            Look {
                shape: "Block",
                material: "Grass",
                color: [75, 151, 75],
                transparency: 0.0,
            },
            Vec3::new(side + 8.0, 1.0, side + 8.0),
            CFrame::new(Vec3::new(0.0, -0.5, 0.0)),
            None,
        )?;
        let others = count.saturating_sub(1);
        let glass_every = others.checked_div(see_through).unwrap_or(0);
        let move_every = 100;
        for i in 0..others {
            let mut look = self.city_look();
            if glass_every > 0 && i % glass_every == glass_every - 1 && self.see_through < see_through {
                look = Look {
                    shape: "Block",
                    material: "Glass",
                    color: [175, 221, 255],
                    transparency: 0.5,
                };
            }
            let size = if look.shape == "Ball" {
                Vec3::splat(self.rng.range(1.0, 4.0))
            } else {
                Vec3::new(
                    self.rng.range(1.0, 4.0),
                    self.rng.range(1.0, 6.0),
                    self.rng.range(1.0, 4.0),
                )
            };
            let x = self.rng.range(-side / 2.0, side / 2.0);
            let z = self.rng.range(-side / 2.0, side / 2.0);
            let turn = Quat::from_rotation_y(self.rng.range(0.0, std::f32::consts::TAU));
            let cframe = CFrame::from_parts(Vec3::new(x, size.y / 2.0, z), turn);
            let id = self.part(look, size, cframe, None)?;
            if i % move_every == move_every / 2 {
                self.moving(id, cframe);
            }
        }
        self.set_camera(Vec3::new(0.0, 6.0, 0.0), Vec3::new(100.0, 0.0, 0.0), 70.0)
    }

    /// 2,500 parts of a town and 1,152 lamps with lights.
    fn lit_town(&mut self) -> Result<(), StressError> {
        let registry = self.dm.registry().clone();
        let point = registry
            .class_id("PointLight")
            .ok_or(StressError::Missing("PointLight class"))?;
        let spot = registry
            .class_id("SpotLight")
            .ok_or(StressError::Missing("SpotLight class"))?;
        let side = 160.0;
        self.part(
            Look {
                shape: "Block",
                material: "Concrete",
                color: [128, 126, 120],
                transparency: 0.0,
            },
            Vec3::new(side + 8.0, 1.0, side + 8.0),
            CFrame::new(Vec3::new(0.0, -0.5, 0.0)),
            None,
        )?;
        // Houses on a grid: 2,499 blocks, wedges and the occasional round thing.
        for _ in 0..2_499 {
            let look = self.city_look();
            let size = Vec3::new(
                self.rng.range(1.0, 6.0),
                self.rng.range(1.0, 8.0),
                self.rng.range(1.0, 6.0),
            );
            let x = self.rng.range(-side / 2.0, side / 2.0);
            let z = self.rng.range(-side / 2.0, side / 2.0);
            self.part(look, size, CFrame::new(Vec3::new(x, size.y / 2.0, z)), None)?;
        }
        let (brightness, color, range, shadows) = (
            registry
                .prop_id(point, "Brightness")
                .ok_or(StressError::Missing("Brightness"))?,
            registry.prop_id(point, "Color").ok_or(StressError::Missing("Color"))?,
            registry.prop_id(point, "Range").ok_or(StressError::Missing("Range"))?,
            registry
                .prop_id(point, "Shadows")
                .ok_or(StressError::Missing("Shadows"))?,
        );
        let angle = registry.prop_id(spot, "Angle").ok_or(StressError::Missing("Angle"))?;
        let spot_cframe = registry.prop_id(spot, "CFrame").ok_or(StressError::Missing("CFrame"))?;
        let warm = [
            [255, 214, 170],
            [255, 180, 120],
            [255, 240, 220],
            [170, 200, 255],
            [255, 120, 200],
        ];
        for i in 0..1_152 {
            let is_spot = i % 9 == 8;
            let tint = self.rng.pick(&warm);
            let x = self.rng.range(-side / 2.0, side / 2.0);
            let z = self.rng.range(-side / 2.0, side / 2.0);
            let height = if is_spot { 9.0 } else { self.rng.range(2.0, 6.0) };
            let rest = CFrame::new(Vec3::new(x, height, z));
            let lamp = self.part(
                Look {
                    shape: "Ball",
                    material: "Neon",
                    color: tint,
                    transparency: 0.0,
                },
                Vec3::splat(0.6),
                rest,
                None,
            )?;
            let light = self.dm.create(if is_spot { spot } else { point })?;
            let [r, g, b] = tint;
            self.dm
                .set(light, brightness, Value::Number(f64::from(self.rng.range(1.0, 4.0))))?;
            self.dm.set(light, color, Value::Color3(Color3::from_rgb_u8(r, g, b)))?;
            self.dm
                .set(light, range, Value::Number(f64::from(self.rng.range(8.0, 24.0))))?;
            if i % 72 == 0 {
                self.dm.set(light, shadows, Value::Bool(true))?;
            }
            if is_spot {
                self.dm
                    .set(light, angle, Value::Number(f64::from(self.rng.range(30.0, 75.0))))?;
                // Pointing down: forward (-Z) turned to -Y.
                let down = CFrame::from_rotation(Quat::from_rotation_x(-std::f32::consts::FRAC_PI_2));
                self.dm.set(light, spot_cframe, Value::CFrame(down))?;
            }
            self.dm.set_parent(light, Some(lamp))?;
            self.lights += 1;
            if i % 100 == 50 {
                self.moving(lamp, rest);
            }
        }
        self.set_camera(Vec3::new(0.0, 30.0, 95.0), Vec3::new(0.0, 0.0, 0.0), 70.0)
    }

    /// A hall 120 m wide, 60 m tall and 44 m deep, crossed by 64 walls with a window each from 2 m to 41 m in
    /// front of the camera, glass in a tenth of the windows, and 3,000 crates on the floor. The hall is wide and
    /// tall enough that every wall covers the whole view but for its window, so a pixel is shaded up to 64 times.
    ///
    /// Built near to far on purpose: the scene's draw lists come out in the reverse of creation order when it is
    /// first attached, so the renderer draws the walls back to front, the worst case for overdraw (measured: 0.54 ms
    /// of GPU on the dev PC, against 0.21 ms when built the other way). A renderer change that sorts opaque
    /// instances or adds a depth prepass (ADR 0008 §7) is what this scene is for.
    fn hall(&mut self) -> Result<(), StressError> {
        let (width, height, length) = (120.0f32, 60.0f32, 44.0f32);
        let shell = Look {
            shape: "Block",
            material: "Concrete",
            color: [150, 146, 140],
            transparency: 0.0,
        };
        let centre_z = -length / 2.0;
        for (size, at) in [
            (Vec3::new(width + 2.0, 1.0, length), Vec3::new(0.0, -0.5, centre_z)),
            (
                Vec3::new(width + 2.0, 1.0, length),
                Vec3::new(0.0, height + 0.5, centre_z),
            ),
            (
                Vec3::new(1.0, height, length),
                Vec3::new(-width / 2.0 - 0.5, height / 2.0, centre_z),
            ),
            (
                Vec3::new(1.0, height, length),
                Vec3::new(width / 2.0 + 0.5, height / 2.0, centre_z),
            ),
        ] {
            self.part(shell, size, CFrame::new(at), None)?;
        }
        // Crates between the walls, near first like the walls.
        let mut crates = Vec::with_capacity(3_000);
        for _ in 0..3_000 {
            let s = self.rng.range(0.5, 2.0);
            let at = Vec3::new(
                self.rng.range(-width / 2.0 + 1.0, width / 2.0 - 1.0),
                s / 2.0,
                self.rng.range(-length + 2.0, -4.0),
            );
            crates.push((s, at));
        }
        crates.sort_by(|a, b| b.1.z.total_cmp(&a.1.z));
        for (i, (s, at)) in crates.into_iter().enumerate() {
            let look = Look {
                shape: "Block",
                material: "Wood",
                color: self.rng.pick(&PALETTE),
                transparency: 0.0,
            };
            let turn = Quat::from_rotation_y(self.rng.range(0.0, std::f32::consts::TAU));
            let rest = CFrame::from_parts(at, turn);
            let id = self.part(look, Vec3::splat(s), rest, None)?;
            if i % 100 == 50 {
                self.moving(id, rest);
            }
        }
        // 64 walls from the near end to the far one, each built around a window somewhere in the view, a few
        // percent of it, so the walls behind show through.
        let walls = 64;
        let thickness = 0.4;
        let (eye_y, tan_y) = (12.0f32, 0.7f32);
        for w in 0..walls {
            let z = -3.0 - 39.0 * w as f32 / (walls - 1) as f32;
            let distance = -z - 1.0;
            let color = self.rng.pick(&PALETTE);
            let wall = Look {
                shape: "Block",
                material: "Plastic",
                color,
                transparency: 0.0,
            };
            let view_h = tan_y * distance;
            let (win_w, win_h) = (self.rng.range(0.3, 0.6) * view_h, self.rng.range(0.2, 0.4) * view_h);
            let win_x = self.rng.range(-1.2, 1.2) * view_h;
            let win_y = (eye_y - 0.1 * distance + self.rng.range(-0.7, 0.7) * view_h)
                .clamp(win_h / 2.0 + 0.5, height - win_h / 2.0 - 0.5);
            let (left, right) = (win_x - win_w / 2.0, win_x + win_w / 2.0);
            let (bottom, top) = (win_y - win_h / 2.0, win_y + win_h / 2.0);
            let half = width / 2.0;
            // Left, right, below and above the window.
            for (x0, x1, y0, y1) in [
                (-half, left, 0.0, height),
                (right, half, 0.0, height),
                (left, right, 0.0, bottom),
                (left, right, top, height),
            ] {
                let size = Vec3::new(x1 - x0, y1 - y0, thickness);
                if size.x > 0.01 && size.y > 0.01 {
                    let at = Vec3::new((x0 + x1) / 2.0, (y0 + y1) / 2.0, z);
                    self.part(wall, size, CFrame::new(at), None)?;
                }
            }
            if w % 10 == 5 {
                let glass = Look {
                    shape: "Block",
                    material: "Glass",
                    color: [175, 221, 255],
                    transparency: 0.6,
                };
                self.part(
                    glass,
                    Vec3::new(win_w, win_h, 0.1),
                    CFrame::new(Vec3::new(win_x, win_y, z)),
                    None,
                )?;
            }
        }
        self.set_camera(Vec3::new(0.0, 12.0, -1.0), Vec3::new(0.0, 8.0, -length), 70.0)
    }

    /// 10,000 see-through parts on a 25 × 20 × 20 lattice, 3 m apart, blocks and balls alternating in every
    /// direction, over an opaque floor; seen along the lattice's diagonal so their back-to-front order interleaves.
    fn lattice(&mut self) -> Result<(), StressError> {
        let (nx, ny, nz) = (25usize, 20usize, 20usize);
        let spacing = 3.0f32;
        self.part(
            Look {
                shape: "Block",
                material: "Concrete",
                color: [128, 126, 120],
                transparency: 0.0,
            },
            Vec3::new(nx as f32 * spacing + 20.0, 1.0, nz as f32 * spacing + 20.0),
            CFrame::new(Vec3::new(0.0, -0.5, 0.0)),
            None,
        )?;
        self.dm.reserve(nx * ny * nz);
        let origin = Vec3::new(
            -(nx as f32 - 1.0) * spacing / 2.0,
            1.5,
            -(nz as f32 - 1.0) * spacing / 2.0,
        );
        let mut i = 0;
        for x in 0..nx {
            for y in 0..ny {
                for z in 0..nz {
                    let shape = if (x + y + z) % 2 == 0 { "Block" } else { "Ball" };
                    let look = Look {
                        shape,
                        material: if shape == "Block" { "Glass" } else { "SmoothPlastic" },
                        color: self.rng.pick(&PALETTE),
                        transparency: f64::from(self.rng.range(0.3, 0.7)),
                    };
                    let rest = CFrame::new(origin + Vec3::new(x as f32, y as f32, z as f32) * spacing);
                    let id = self.part(look, Vec3::splat(2.0), rest, None)?;
                    if i % 100 == 50 {
                        self.moving(id, rest);
                    }
                    i += 1;
                }
            }
        }
        let extent = Vec3::new(nx as f32, ny as f32, nz as f32) * spacing;
        self.set_camera(
            Vec3::new(extent.x * 0.9, extent.y * 1.1, extent.z * 0.9),
            Vec3::new(0.0, extent.y * 0.4, 0.0),
            70.0,
        )
    }

    fn finish(self, kind: StressKind, seed: u64) -> Result<StressScene, StressError> {
        let (camera, fov) = self.view;
        let in_view = count_in_view(&self.centres, camera, fov, 16.0 / 9.0);
        Ok(StressScene {
            kind,
            seed,
            parts: self.parts,
            see_through: self.see_through,
            lights: self.lights,
            in_view,
            centres: self.centres,
            camera: self.camera,
            view: self.view,
            cframe: self.props.cframe,
            movers: self.movers,
        })
    }
}

/// How many of `points` are inside the view of a camera at `camera` with a vertical field of view of
/// `field_of_view` degrees and the given aspect ratio (no far plane, as the renderer has none).
fn count_in_view(points: &[Vec3], camera: CFrame, field_of_view: f32, aspect: f32) -> usize {
    let to_view = camera.inverse();
    let tan_y = (field_of_view.to_radians() / 2.0).tan();
    let tan_x = tan_y * aspect;
    points
        .iter()
        .filter(|&&p| {
            let v = to_view.transform_point(p);
            let depth = -v.z;
            depth > 0.1 && v.x.abs() <= depth * tan_x && v.y.abs() <= depth * tan_y
        })
        .count()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn build(kind: StressKind, seed: u64) -> (DataModel, StressScene) {
        let mut dm = metallic_classes::new_game().expect("a game");
        let scene = StressScene::build(&mut dm, kind, seed).expect("the scene");
        (dm, scene)
    }

    /// Every part's `CFrame`, `Size` and `Transparency` under `Workspace`, in tree order.
    fn snapshot(dm: &DataModel) -> Vec<(Value, Value, Value)> {
        let registry = dm.registry().clone();
        let workspace = dm
            .service(registry.class_id("Workspace").expect("Workspace"))
            .expect("a Workspace");
        let part = registry.class_id("Part").expect("Part");
        dm.descendants(workspace)
            .expect("Workspace's descendants")
            .filter(|&id| dm.class_of(id) == Ok(part))
            .map(|id| {
                let get = |name| dm.get_by_name(id, name).expect(name);
                (get("CFrame"), get("Size"), get("Transparency"))
            })
            .collect()
    }

    #[test]
    fn names_round_trip() {
        for kind in StressKind::ALL {
            assert_eq!(StressKind::from_name(kind.name()), Some(kind));
        }
        assert_eq!(StressKind::from_name("nope"), None);
        let mut dm = metallic_classes::new_game().expect("a game");
        let error = StressScene::build_named(&mut dm, "nope", 1).expect_err("no such scene");
        assert!(error.to_string().contains("parts_100k"), "{error}");
    }

    #[test]
    fn the_same_seed_builds_the_same_scene() {
        let (a, scene_a) = build(StressKind::Mobile, 7);
        let (b, _) = build(StressKind::Mobile, 7);
        let (c, _) = build(StressKind::Mobile, 8);
        assert_eq!(snapshot(&a), snapshot(&b));
        assert_ne!(snapshot(&a), snapshot(&c));
        assert_eq!(scene_a.parts(), 5_000);
        assert_eq!(scene_a.see_through(), 25);
        assert_eq!(scene_a.moving(), 50);
        assert_eq!(snapshot(&a).len(), 5_000);
    }

    #[test]
    fn the_part_scenes_have_their_counts_and_one_percent_moving() {
        let (_, scene) = build(StressKind::Parts10k, 1);
        assert_eq!(scene.parts(), 10_000);
        assert_eq!(scene.moving(), 100);
        assert_eq!(scene.see_through(), 0);
        assert!(
            scene.in_view() > 1_000 && scene.in_view() < 9_000,
            "{}",
            scene.in_view()
        );
    }

    #[test]
    fn the_light_scene_builds_light_instances_in_lamps() {
        let (dm, scene) = build(StressKind::ManyLights, 1);
        assert_eq!(scene.lights(), 1_152);
        assert_eq!(scene.parts(), 2_500 + 1_152);
        let registry = dm.registry().clone();
        let light = registry.class_id("Light").expect("Light");
        let workspace = dm
            .service(registry.class_id("Workspace").expect("Workspace"))
            .expect("a Workspace");
        let lights = dm
            .descendants(workspace)
            .expect("Workspace's descendants")
            .filter(|&id| dm.is_a(id, light) == Ok(true))
            .count();
        assert_eq!(lights, 1_152);
    }

    #[test]
    fn the_overdraw_and_see_through_scenes_build() {
        let (_, hall) = build(StressKind::Overdraw, 1);
        assert!(hall.parts() > 3_000 + 64 * 3, "{}", hall.parts());
        assert!(hall.see_through() >= 6);
        assert_eq!(hall.moving(), 30);
        let (_, lattice) = build(StressKind::SeeThrough10k, 1);
        assert_eq!(lattice.parts(), 10_001);
        assert_eq!(lattice.see_through(), 10_000);
        assert_eq!(lattice.moving(), 100);
        assert!(lattice.in_view() > 5_000, "{}", lattice.in_view());
    }

    /// ADR 0008's scale target, culled on the CPU (#79): a camera that sees about 10% of `parts_100k` draws about
    /// 10% of its instances. A part is kept when its bounding sphere reaches into the view, so a few more than the
    /// parts whose centre is in view.
    #[cfg(feature = "render")]
    #[test]
    fn a_camera_seeing_a_tenth_of_parts_100k_draws_about_a_tenth() {
        use metallic_render::scene::RenderComponents;
        use metallic_render::{CameraReader, CullSettings, CullView, InstanceScene, VisibleSet};

        let (mut dm, mut scene) = build(StressKind::Parts100k, 1);
        scene.set_field_of_view(&mut dm, 26.0).expect("FieldOfView");
        let in_view = scene.in_view();
        assert!((8_000..12_000).contains(&in_view), "{in_view} parts in view");

        let registry = dm.registry().clone();
        let workspace = dm
            .service(registry.class_id("Workspace").expect("Workspace"))
            .expect("a Workspace");
        let mut instances =
            InstanceScene::attach(&mut dm, Some(workspace), &RenderComponents::builtin()).expect("a scene");
        instances.sync(&mut dm);
        instances.coalesce();
        let camera = CameraReader::new().read(&dm, workspace).expect("a camera");
        let view = CullView::for_camera(&camera, instances.origin(), 1920, 1080, &CullSettings::default());
        let mut visible = VisibleSet::new();
        let stats = instances.cull(&view, &mut visible);
        eprintln!("{in_view} parts in view: {stats:?}");
        assert_eq!(stats.candidates, 100_000);
        assert_eq!(visible.len(), stats.visible as usize);
        let drawn = stats.visible as usize;
        assert!(
            drawn >= in_view && drawn <= in_view + in_view / 5,
            "{drawn} drawn for {in_view} parts in view"
        );
        // Most of the grid is skipped a whole cell at a time.
        assert!(stats.cells_outside * 2 > stats.cells, "{stats:?}");
    }

    #[test]
    fn animation_moves_only_the_moving_parts_and_repeats() {
        let (mut dm, scene) = build(StressKind::Mobile, 3);
        let rest = snapshot(&dm);
        scene.animate(&mut dm, 1.25).expect("animate");
        let moved = snapshot(&dm);
        let changed = rest.iter().zip(&moved).filter(|(a, b)| a != b).count();
        assert_eq!(changed, scene.moving());
        scene.animate(&mut dm, 2.0).expect("animate");
        scene.animate(&mut dm, 1.25).expect("animate");
        assert_eq!(snapshot(&dm), moved, "the same time gives the same frame");
    }

    #[test]
    fn view_counting_uses_the_camera() {
        let camera = CFrame::look_at(Vec3::ZERO, Vec3::new(0.0, 0.0, -1.0), Vec3::Y);
        let points = [
            Vec3::new(0.0, 0.0, -10.0),
            Vec3::new(0.0, 0.0, 10.0),
            Vec3::new(100.0, 0.0, -10.0),
            Vec3::new(0.0, 6.0, -10.0),
        ];
        // 70° vertical: tan(35°) * 10 = 7 m up and down at 10 m.
        assert_eq!(count_in_view(&points, camera, 70.0, 16.0 / 9.0), 2);
    }
}
